    public String parseTransactionStatus(String status)
    {
        // deposit state includes: 1 (in deposit), 2 (to be confirmed), 3 (successfully deposited), 4 (stopped)
        // withdrawal state includes: 1 (application in progress), 2 (to be confirmed), 3 (completed), 4 (rejected)
        Map<String, Object> statuses = new HashMap<String, Object>() {{
            put( "1", "pending" );
            put( "2", "pending" );
            put( "3", "ok" );
            put( "4", "failed" );
        }};
        return this.safeString(statuses, status, status);
    }

    public Object parseTransaction(Map<String, Object> transaction, Map<String, Object> currency)
    {
        //
        // withdraw
        //
        //     {
        //         "code": 200,
        //         "withdraw_id": 700
        //     }
        //
        // fetchDeposits, fetchWithdrawals
        //
        //     {
        //         "id": 1171,
        //         "currency": "xrp",
        //         "hash": "ed03094b84eafbe4bc16e7ef766ee959885ee5bcb265872baaa9c64e1cf86c2b",
        //         "chain": "",
        //         "amount": 7.457467,
        //         "address": "rae93V8d2mdoUQHwBDBdM4NHCMehRJAsbm",
        //         "memo": "100040",
        //         "fee": 0,
        //         "state": "safe",
        //         "created_date": "2020-04-20 11:23:00",
        //         "finished_date": "2020-04-20 13:23:00"
        //     }
        //
        String id = this.safeString2(transaction, "id", "withdraw_id");
        String address = this.safeString(transaction, "address");
        String tag = this.safeString(transaction, "memo");
        String txid = this.safeString(transaction, "hash");
        String currencyId = this.safeStringUpper(transaction, "currency");
        String code = this.safeCurrencyCode(currencyId, currency);
        Long timestamp = this.parse8601(this.safeString(transaction, "created_date"));
        Long updated = this.parse8601(this.safeString(transaction, "finished_date"));
        String status = this.parseTransactionStatus(this.safeString(transaction, "state"));
        Double amount = this.safeNumber(transaction, "amount");
        Double feeCost = this.safeNumber(transaction, "fee");
        Map<String, Object> fee = null;
        if (!java.util.Objects.equals(feeCost, null))
        {
            final Double finalFeeCost = feeCost;
            fee = new HashMap<String, Object>() {{
                put( "currency", code );
                put( "cost", finalFeeCost );
            }};
        }
        String network = this.safeString(transaction, "chain");
        final Map<String, Object> finalFee = fee;
        return new HashMap<String, Object>() {{
            put( "info", transaction );
            put( "id", id );
            put( "txid", txid );
            put( "timestamp", timestamp );
            put( "datetime", Digifinex.this.iso8601(timestamp) );
            put( "network", network );
            put( "address", address );
            put( "addressTo", address );
            put( "addressFrom", null );
            put( "tag", tag );
            put( "tagTo", tag );
            put( "tagFrom", null );
            put( "type", null );
            put( "amount", amount );
            put( "currency", code );
            put( "status", status );
            put( "updated", updated );
            put( "internal", null );
            put( "comment", null );
            put( "fee", finalFee );
        }};
    }
    public Object parseTransaction(Map<String, Object> transaction, Object... optionalArgs)
    {
        return this.parseTransaction(transaction, Helpers.getArgMap(optionalArgs, 0, null));
    }

