    /**
     * @method
     * @name digifinex#fetchPositions
     * @description fetch all open positions
     * @see https://docs.digifinex.com/en-ww/spot/v3/rest.html#margin-positions
     * @see https://docs.digifinex.com/en-ww/swap/v2/rest.html#positions
     * @param {string[]|undefined} symbols list of unified market symbols
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object[]} a list of [position structures]{@link https://docs.ccxt.com/?id=position-structure}
     */
    public CompletableFuture<List<Position>> fetchPositions(List<String> symbols2, Map<String, Object> parameters2)
    {
        final List<String> symbols3 = symbols2;
        final Map<String, Object> parameters3 = parameters2;
        return BaseExchange.supplyAsync(() -> {
            List<String> symbols = symbols3;
            Map<String, Object> parameters = parameters3;
            if (java.util.Objects.equals(this.markets, null))
            {
                (this.loadMarkets()).join();
            }
            symbols = Helpers.toStringListArg(this.marketSymbols(symbols));
            Map<String, Object> request = new HashMap<String, Object>() {{}};
            Map<String, Object> market = null;
            String marketType = null;
            if (!java.util.Objects.equals(symbols, null))
            {
                Object symbol = null;
                if ((symbols instanceof List))
                {
                    Integer symbolsLength = ((List<?>)symbols).size();
                    if (Helpers.isGreaterThan(symbolsLength, 1))
                    {
                        throw new BadRequest((this.id + " fetchPositions() symbols argument cannot contain more than 1 symbol")) ;
                    }
                    symbol = (symbols == null || 0 >= ((List<?>)symbols).size() ? null : ((List<?>)symbols).get(0));
                } else
                {
                    symbol = symbols;
                }
                market = (Map<String, Object>) this.market(symbol);
            }
            List<Object> marketTypeparametersVariable = (List<Object>) this.handleMarketTypeAndParams("fetchPositions", market, parameters);
            marketType = (String) ((List<Object>) marketTypeparametersVariable).get(0);
            parameters = (Map<String, Object>) ((List<Object>) marketTypeparametersVariable).get(1);
            List<Object> marginModequeryVariable = (List<Object>) this.handleMarginModeAndParams("fetchPositions", parameters);
            String marginMode = (String) ((List<Object>) marginModequeryVariable).get(0);
            var query = ((List<Object>) marginModequeryVariable).get(1);
            if (!java.util.Objects.equals(marginMode, null))
            {
                marketType = "margin";
            }
            if (!java.util.Objects.equals(market, null))
            {
                String marketIdRequest = "symbol";
                if (java.util.Objects.equals(marketType, "swap"))
                {
                    marketIdRequest = "instrument_id";
                }
                ((Map<String, Object>)request).put((String)marketIdRequest, ((Map<String, Object>)market).get("id"));
            }
            Map<String, Object> response = null;
            if (java.util.Objects.equals(marketType, "spot") || java.util.Objects.equals(marketType, "margin"))
            {
                response = (this.privateSpotGetMarginPositions(this.extend(request, query))).join();
            } else if (java.util.Objects.equals(marketType, "swap"))
            {
                response = (this.privateSwapGetAccountPositions(this.extend(request, query))).join();
            } else
            {
                throw new NotSupported((this.id + " fetchPositions() not support this market type")) ;
            }
            //
            // swap
            //
            //     {
            //         "code": 0,
            //         "data": [
            //             {
            //                 "instrument_id": "BTCUSDTPERP",
            //                 "margin_mode": "crossed",
            //                 "avail_position": "1",
            //                 "avg_cost": "18369.3",
            //                 "last": "18404.7",
            //                 "leverage": "20",
            //                 "liquidation_price": "451.12820512820264",
            //                 "maint_margin_ratio": "0.005",
            //                 "margin": "0.918465",
            //                 "position": "1",
            //                 "realized_pnl": "0",
            //                 "unrealized_pnl": "0.03410000000000224",
            //                 "unrealized_pnl_rate": "0.03712716325608732",
            //                 "side": "long",
            //                 "open_outstanding": "0",
            //                 "risk_score": "0.495049504950495",
            //                 "margin_ratio": "0.4029464788983229",
            //                 "timestamp": 1667960497145
            //             },
            //             ...
            //         ]
            //     }
            //
            // margin
            //
            //     {
            //         "margin": "77.71534772983289",
            //         "code": 0,
            //         "margin_rate": "10.284503769497306",
            //         "positions": [
            //             {
            //                 "amount": 0.0010605,
            //                 "side": "go_long",
            //                 "entry_price": 18321.39,
            //                 "liquidation_rate": 0.3,
            //                 "liquidation_price": -52754.371758471,
            //                 "unrealized_roe": -0.002784390267332,
            //                 "symbol": "BTC_USDT",
            //                 "unrealized_pnl": -0.010820048189999,
            //                 "leverage_ratio": 5
            //             },
            //             ...
            //         ],
            //         "unrealized_pnl": "-0.10681600018999979"
            //     }
            //
            String positionRequest = "positions";
            if (java.util.Objects.equals(marketType, "swap"))
            {
                positionRequest = "data";
            }
            List<Object> positions = (List<Object>) this.safeList(response, positionRequest, new ArrayList<Object>(Arrays.asList()));
            List<Object> result = new ArrayList<Object>(Arrays.asList());
            for (var i = 0; i < ((List<?>)positions).size(); i++)
            {
                ((List<Object>)result).add(this.parsePosition((Map<String, Object>) ((positions == null || i < 0 || i >= positions.size() ? null : positions.get(i))), market));
            }
            return this.filterByArrayPositions(result, "symbol", symbols, false);
        }).thenApply(res -> ((List<?>) res).stream().map(Position::new).collect(Collectors.toList()));

    }
